INSERT INTO notes (date,area,severity,title,body,metric) VALUES ('2026-08-28','cash','do-now','Three jobs finished but never invoiced','Reid, Casuarina Grove and the Whitlam driveway all closed out last week with no invoice raised.','$31,900 sitting uninvoiced, the biggest single item this month'),('2026-08-28','quotes','watch','Six quotes past two weeks with no follow-up','Conversion drops off hard after a fortnight. The Ferguson job is the one worth ringing first.','$74,200 of quoted work going cold'),('2026-08-28','cash','good','Debtor days down for the seventh week running','The Monday chase habit is working. 41 days, from 52 in early July.','41 days vs 52 eight weeks ago');
INSERT INTO todos (title,detail,source,priority) VALUES ('Invoice Reid retaining wall JOB-4471','Finished 19 Aug, $18,400, still not raised','routine',1),('Invoice Casuarina Grove landscaping JOB-4468','Finished 21 Aug, $9,100','routine',1),('Follow up Ferguson quote Q-1182','Sent 11 Aug, $34,600, no response','routine',1),('Chase Henderson invoice INV-2291','63 days overdue, $8,400','routine',1),('Order turf for the Marsden job','Booked to start 4 Sep','routine',2),('Book the mini excavator for w/c 8 Sep','Two jobs need it the same week','routine',2);
INSERT INTO runs (skill_id,title,status,summary_html,detail_html,run_at) VALUES ('morning-brief','Morning brief','warn','<p><b>Three finished jobs still have no invoice raised.</b></p><ul><li>$31,900 uninvoiced, oldest closed 9 days ago</li><li>Cash at bank $48,210, up 5% on last week</li><li>11 jobs active, 13 quotes out</li></ul>','<h1 style="font:600 22px system-ui">Morning brief</h1><p style="font:15px/1.6 system-ui;max-width:620px">Three jobs closed out in the last fortnight and none of them have been invoiced: Reid ($18,400, finished 19 Aug), Casuarina Grove ($9,100, 21 Aug) and the Whitlam driveway ($4,400, 24 Aug). That is the single biggest thing on the board this morning and all three are straightforward.</p><p style="font:15px/1.6 system-ui;max-width:620px">Cash is $48,210, comfortably ahead of the $22,000 of bills due before the 10th. Debtor days at 41, down from 52 in July.</p><p style="font:13px system-ui;color:#777">Jobs data from Monday 25 Aug export, 3 days old.</p>','2026-08-28T07:00:00+10:00'),('cash-and-debtors','Cash and debtors','ok','<p><b>Nothing urgent. The chase habit is holding.</b></p><ul><li>Debtor days 41, down from 52</li><li>Two invoices over 60 days, worth $11,600</li><li>Cash covers the next fortnight comfortably</li></ul>','<h1 style="font:600 22px system-ui">Cash and debtors</h1><p style="font:15px/1.6 system-ui;max-width:620px">Receivables at $42,650 across 19 invoices. Two are past 60 days: Henderson INV-2291 ($8,400, 63 days) and Blackwood INV-2264 ($3,200, 71 days). Henderson is the one worth a call, and it is worth checking whether the variation on that job was ever agreed before ringing.</p>','2026-08-27T07:00:00+10:00'),('jobs-and-quotes','Jobs and quotes','warn','<p><b>Six quotes are past the two week mark.</b></p><ul><li>$74,200 of quoted work with no follow-up</li><li>11 jobs active, 3 finished awaiting invoice</li><li>Pipeline thinner than this time last month</li></ul>','<h1 style="font:600 22px system-ui">Jobs and quotes</h1><p style="font:15px/1.6 system-ui;max-width:620px">Quoted value out is $138,500, down from $163,000 a fortnight ago. Six quotes are now past 14 days without a follow-up, and on the last three months of data this business converts 41% inside two weeks and 12% after.</p><p style="font:13px system-ui;color:#777">Built from the 25 Aug Tradify export.</p>','2026-08-27T07:00:00+10:00');
INSERT OR REPLACE INTO pages (slug,title,html,nav,sort,updated_at) VALUES ('jobs','Jobs','<html><body style="font:15px/1.6 -apple-system,system-ui;padding:26px;color:#14140f"><h1 style="font-size:21px;margin-bottom:4px">Jobs and quotes</h1><p style="color:#777;font-size:13px;margin-bottom:20px">From the Tradify export of 25 Aug 2026.</p><h2 style="font-size:13px;text-transform:uppercase;letter-spacing:.08em;color:#777;margin:22px 0 8px">Finished, not invoiced</h2><table style="border-collapse:collapse;width:100%;max-width:680px"><tr style="text-align:left;border-bottom:2px solid #14140f"><th style="padding:7px 8px">Job</th><th style="padding:7px 8px">Customer</th><th style="padding:7px 8px">Finished</th><th style="padding:7px 8px;text-align:right">Value</th></tr><tr style="border-bottom:1px solid #e3e2da"><td style="padding:7px 8px">JOB-4471</td><td style="padding:7px 8px">Reid</td><td style="padding:7px 8px">19 Aug</td><td style="padding:7px 8px;text-align:right">$18,400</td></tr><tr style="border-bottom:1px solid #e3e2da"><td style="padding:7px 8px">JOB-4468</td><td style="padding:7px 8px">Casuarina Grove</td><td style="padding:7px 8px">21 Aug</td><td style="padding:7px 8px;text-align:right">$9,100</td></tr><tr style="border-bottom:1px solid #e3e2da"><td style="padding:7px 8px">JOB-4475</td><td style="padding:7px 8px">Whitlam</td><td style="padding:7px 8px">24 Aug</td><td style="padding:7px 8px;text-align:right">$4,400</td></tr></table><h2 style="font-size:13px;text-transform:uppercase;letter-spacing:.08em;color:#777;margin:26px 0 8px">Quotes going cold</h2><table style="border-collapse:collapse;width:100%;max-width:680px"><tr style="text-align:left;border-bottom:2px solid #14140f"><th style="padding:7px 8px">Quote</th><th style="padding:7px 8px">Customer</th><th style="padding:7px 8px">Sent</th><th style="padding:7px 8px;text-align:right">Value</th></tr><tr style="border-bottom:1px solid #e3e2da"><td style="padding:7px 8px">Q-1182</td><td style="padding:7px 8px">Ferguson</td><td style="padding:7px 8px">11 Aug</td><td style="padding:7px 8px;text-align:right">$34,600</td></tr><tr style="border-bottom:1px solid #e3e2da"><td style="padding:7px 8px">Q-1176</td><td style="padding:7px 8px">Nguyen</td><td style="padding:7px 8px">8 Aug</td><td style="padding:7px 8px;text-align:right">$16,900</td></tr><tr style="border-bottom:1px solid #e3e2da"><td style="padding:7px 8px">Q-1171</td><td style="padding:7px 8px">Delaney</td><td style="padding:7px 8px">5 Aug</td><td style="padding:7px 8px;text-align:right">$12,300</td></tr></table></body></html>',1,10,'2026-08-28');
